// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the system time.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket starts full and refills at rate tokens per interval.
type Limiter struct {
	mu        sync.Mutex
	tokens    float64
	last      time.Time
	rate      float64 // tokens per interval
	burst     float64 // max tokens
	interval  time.Duration
	clock     Clock
}

var (
	ErrNonPositiveRate     = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst    = errors.New("ratelimit: burst must be > 0")
	ErrNonPositiveInterval = errors.New("ratelimit: interval must be > 0")
	ErrNilClock            = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter that refills rate tokens every interval,
// with a maximum capacity of burst tokens. The bucket starts full.
func New(rate int, burst int, interval time.Duration, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if interval <= 0 {
		return nil, ErrNonPositiveInterval
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	return &Limiter{
		tokens:   float64(burst),
		last:     clock.Now(),
		rate:     float64(rate),
		burst:    float64(burst),
		interval: interval,
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are deducted.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill based on elapsed intervals.
	elapsed := now.Sub(l.last)
	if elapsed > 0 {
		l.tokens += elapsed.Seconds() / l.interval.Seconds() * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}

	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}
