// ratelimit_test.go
package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	t time.Time
}

func (c *fakeClock) Now() time.Time { return c.t }
func (c *fakeClock) Advance(d time.Duration) {
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clock := &fakeClock{t: time.Unix(0, 0)}
	cases := []struct {
		name     string
		rate     int
		burst    int
		interval time.Duration
		clock    Clock
		wantErr  error
	}{
		{"zero rate", 0, 1, time.Second, clock, ErrNonPositiveRate},
		{"negative rate", -1, 1, time.Second, clock, ErrNonPositiveRate},
		{"zero burst", 1, 0, time.Second, clock, ErrNonPositiveBurst},
		{"zero interval", 1, 1, 0, clock, ErrNonPositiveInterval},
		{"nil clock", 1, 1, time.Second, nil, ErrNilClock},
		{"valid", 1, 1, time.Second, clock, nil},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			l, err := New(tc.rate, tc.burst, tc.interval, tc.clock)
			if tc.wantErr == nil {
				if err != nil {
					t.Fatalf("unexpected error: %v", err)
				}
				if l == nil {
					t.Fatal("expected limiter")
				}
				return
			}
			if err != tc.wantErr {
				t.Fatalf("got %v, want %v", err, tc.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	newLimiter := func(t *testing.T, clock Clock) *Limiter {
		l, err := New(10, 5, time.Second, clock)
		if err != nil {
			t.Fatalf("New: %v", err)
		}
		return l
	}

	cases := []struct {
		name  string
		steps []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name: "burst then deny",
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 5, true},
				{0, 1, false},
			},
		},
		{
			name: "partial refill",
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 5, true},
				{500 * time.Millisecond, 5, false}, // only 5 tokens refilled
				{0, 5, true},
			},
		},
		{
			name: "refill capped at burst",
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 5, true},
				{10 * time.Second, 5, true},
				{0, 1, false},
			},
		},
		{
			name: "zero tokens always allowed",
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 0, true},
				{0, 0, true},
			},
		},
		{
			name: "negative n denied",
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, -1, false},
				{0, 5, true},
			},
		},
		{
			name: "time going backwards does not refill",
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 5, true},
				{-time.Second, 1, false},
			},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clock := &fakeClock{t: base}
			l := newLimiter(t, clock)
			for i, s := range tc.steps {
				clock.Advance(s.advance)
				if got := l.AllowN(clock.Now(), s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllowUsesClock(t *testing.T) {
	clock := &fakeClock{t: time.Unix(0, 0)}
	l, err := New(1, 1, time.Second, clock)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	if !l.Allow() {
		t.Fatal("first Allow should succeed")
	}
	if l.Allow() {
		t.Fatal("second Allow should fail")
	}
	clock.Advance(time.Second)
	if !l.Allow() {
		t.Fatal("Allow after refill should succeed")
	}
}

func TestConcurrentAccess(t *testing.T) {
	clock := &fakeClock{t: time.Unix(0, 0)}
	l, err := New(1000, 100, time.Second, clock)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.AllowN(clock.Now(), 1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Fatalf("allowed = %d, want 100", allowed)
	}
}
